/// <summary>
/// NDX_MultipleSelect_QuotationRange
/// </summary>
class NDX_MultipleSelect_QuotationRange extends NDX_MultipleSelect
{
    NDXMultipleS_SalesQuotationRange   nDX_SelectionTmp;        // Vorlagedaten für die Selektion der bereits markierten Datensätze
    QuotationIdBase                quotationId;


}

Method.Source:
void closedSelectForm()
{
    FormDataSource  formDatasource;
    int             i, nBis;
    tableId         tableId;
    ;

    nBis = selectForm.dataSourceCount();
    for (i = 1; i <= nBis; i++)
    {
        formDataSource  = selectForm.dataSource(i);
        tableId         = formDataSource.table();
        if (tableId == tablenum(NDXMultipleS_SalesQuotationRange))
        {
            nDX_SelectionTmp.data(formDatasource.cursor());
            break;
        }
    }
}

public boolean isRangeEmpty()
{
    select count(RecId) from nDX_SelectionTmp;
    return nDX_SelectionTmp.RecId == 0;
}
